#include <iostream>
#include <vector>
#include <algorithm>
#include <deque>

using namespace std;

const long long INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;

    vector<long long> A(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> A[i];
    }

    vector<long long> dp(n + 1, -INF);
    dp[0] = 0;

    long long global_ans = -INF;

    for (int j = 1; j <= k; j++) {
        vector<long long> next_dp(n + 1, -INF);
        deque<int> q;

        for (int i = 1; i <= n; i++) {
            int new_k = i - 1;
            if (dp[new_k] != -INF) {
                while (!q.empty() && dp[q.back()] <= dp[new_k]) {
                    q.pop_back();
                }
                q.push_back(new_k);
            }

            while (!q.empty() && q.front() < i - m - 1) {
                q.pop_front();
            }

            if (!q.empty()) {
                next_dp[i] = dp[q.front()] + A[i];
            }
        }

        dp = move(next_dp);

        for (int i = max(0, n - m); i <= n; i++) {
            if (dp[i] > global_ans) {
                global_ans = dp[i];
            }
        }
    }

    if (global_ans <= -INF / 2) {
        cout << -1 << "\n";
    } else {
        cout << global_ans << "\n";
    }

    return 0;
}
